using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
namespace IslandGame.Editor {
 public static class ApprovedDioramaSetup {
  const string Key="IslandApprovedDioramaPipeline/",Root="Assets/DioramaPreview/Settings/";
  [MenuItem("Island/Diorama/Apply approved Nilo battle look")]
  static void MenuApply(){Apply();}
  public static object Apply(){if(EditorApplication.isPlaying)throw new Exception("Stop Play before setup");string key=Key+Application.dataPath;
   if(!EditorPrefs.HasKey(key)){EditorPrefs.SetString(key,AssetDatabase.GetAssetPath(GraphicsSettings.defaultRenderPipeline));EditorPrefs.SetString(key+"/quality",string.Join("|",Enumerable.Range(0,QualitySettings.names.Length).Select(i=>AssetDatabase.GetAssetPath(QualitySettings.GetRenderPipelineAssetAt(i)))));}
   var pipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(Root+"DioramaURP.asset");if(!pipeline)throw new Exception("Import the validated diorama assets first");
   var graphics=AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/GraphicsSettings.asset");var quality=AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/QualitySettings.asset");Undo.RecordObjects(graphics.Concat(quality).ToArray(),"Apply approved diorama pipeline");GraphicsSettings.defaultRenderPipeline=pipeline;for(int i=0;i<QualitySettings.names.Length;i++)SetQuality(i,pipeline);
   string settingsPath="Assets/Island/Resources/BattleDioramaSettings.asset";var settings=AssetDatabase.LoadAssetAtPath<BattleDioramaSettings>(settingsPath);if(!settings){settings=ScriptableObject.CreateInstance<BattleDioramaSettings>();AssetDatabase.CreateAsset(settings,settingsPath);}Undo.RecordObject(settings,"Configure approved diorama");
   settings.hero=AssetDatabase.LoadAssetAtPath<Material>(Root+"HeroNilo.mat");settings.boss=AssetDatabase.LoadAssetAtPath<Material>(Root+"BossNilo.mat");settings.cutout=AssetDatabase.LoadAssetAtPath<Material>(Root+"KeepCutout.mat");settings.transparent=AssetDatabase.LoadAssetAtPath<Material>(Root+"KeepUnlit.mat");settings.terrain=AssetDatabase.LoadAssetAtPath<Material>(Root+"KeepTerrain.mat");settings.groundPalette=Resources.Load<TerrainData>("DioramaTerrain");
   settings.lit=Material("BattleLit","Universal Render Pipeline/Lit");settings.normal=Material("BattleNormal","Universal Render Pipeline/Lit");settings.normal.EnableKeyword("_NORMALMAP");settings.normal.SetTexture("_BumpMap",Texture2D.normalTexture);EditorUtility.SetDirty(settings.normal);
   var p=AssetDatabase.LoadAssetAtPath<VolumeProfile>(Root+"BattleVolume.asset");if(!p){p=ScriptableObject.CreateInstance<VolumeProfile>();AssetDatabase.CreateAsset(p,Root+"BattleVolume.asset");}Undo.RecordObject(p,"Battle optional effect presets");var b=Override<Bloom>(p);b.active=true;b.threshold.Override(1.15f);b.intensity.Override(.1f);b.scatter.Override(.4f);b.clamp.Override(2);var d=Override<DepthOfField>(p);d.active=false;d.mode.Override(DepthOfFieldMode.Gaussian);d.gaussianStart.Override(45);d.gaussianEnd.Override(85);d.gaussianMaxRadius.Override(.5f);var v=Override<Vignette>(p);v.active=false;v.intensity.Override(.045f);v.smoothness.Override(.35f);settings.volume=p;EditorUtility.SetDirty(p);EditorUtility.SetDirty(settings);
   foreach(var m in new[]{settings.hero,settings.boss}){Undo.RecordObject(m,"Approved character material");m.SetFloat("_RimStrength",0);m.SetFloat("_OutlineWidth",0);m.SetShaderPassEnabled("Outline",false);m.SetFloat("_ReceiveShadowMappingAmount",.85f);m.SetColor("_IndirectLightMinColor",new Color(.04f,.05f,.065f));EditorUtility.SetDirty(m);}
   AssetDatabase.SaveAssets();return new{pipeline=pipeline.name,qualityLevels=QualitySettings.names.Length,settings=settingsPath,bloom=.1f,dof=false,vignette=false,bakedLightmaps=LightmapSettings.lightmaps.Length,originalMaterialsChanged=false};
  }
  static Material Material(string name,string shader){string path=Root+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find(shader));AssetDatabase.CreateAsset(m,path);}return m;}
  static T Override<T>(VolumeProfile p)where T:VolumeComponent {if(p.TryGet<T>(out var v))return v;v=p.Add<T>(false);AssetDatabase.AddObjectToAsset(v,p);return v;}
  static void SetQuality(int i,RenderPipelineAsset p){int old=QualitySettings.GetQualityLevel();QualitySettings.SetQualityLevel(i,false);QualitySettings.renderPipeline=p;QualitySettings.SetQualityLevel(old,false);}
  [MenuItem("Island/Diorama/Restore pipeline before approved integration")]
  public static void Restore(){if(EditorApplication.isPlaying)throw new Exception("Stop Play before restore");string key=Key+Application.dataPath;if(!EditorPrefs.HasKey(key))return;GraphicsSettings.defaultRenderPipeline=AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>(EditorPrefs.GetString(key));var q=EditorPrefs.GetString(key+"/quality").Split('|');for(int i=0;i<q.Length&&i<QualitySettings.names.Length;i++)SetQuality(i,AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>(q[i]));AssetDatabase.SaveAssets();}
 }
}
